  ('nordic_eccentric', 'Nordic Curl, Eccentric', 'hip_hinge', '{"strength"}', '{"hamstrings"}', '{"glutes","calves"}', '{"mat","anchor_for_feet"}', 4, 3, true, false, false, false, 30, 'reps', 3, 6, false, null, 4, '{"knee_deep_flexion"}', '{"hamstring_walkout","single_leg_romanian_deadlift"}', false, false, 'The best-evidenced hamstring-injury reducer there is, and brutally hard on the first attempt. Lowered slowly, hands ready to catch.', 'resistance_dynamic', 'sets_reps_load', '{}', '{}', '[]'::jsonb, '{}', 4, false, 'none', false, false, false, '{}', 'nordic_eccentric', null, 'internally_reviewed', false, true, false, null, '[]'::jsonb, '{}', 'minimal', 'primary', 'lengthened', true, 'hamstring_eccentric'),
  ('hamstring_walkout', 'Hamstring Walkout', 'hip_hinge', '{"strength"}', '{"hamstrings"}', '{"glutes","core"}', '{"mat"}', 2, 3, true, false, false, false, 5, 'reps', 6, 10, false, null, 3, '{}', '{"single_leg_glute_bridge"}', true, false, 'From a bridge, walking the heels out and back. The regression that makes the Nordic reachable.', 'resistance_dynamic', 'sets_reps_load', '{}', '{}', '[]'::jsonb, '{}', 2, false, 'none', false, false, false, '{}', 'hamstring_walkout', null, 'internally_reviewed', true, true, false, null, '[]'::jsonb, '{}', 'minimal', 'primary', 'lengthened', true, 'hamstring_eccentric'),
  ('band_good_morning', 'Band Good Morning', 'hip_hinge', '{"strength"}', '{"hamstrings","glutes"}', '{"spinal_erectors"}', '{"bands"}', 2, 2, true, false, false, false, 15, 'reps', 12, 20, false, null, 2, '{"lumbar_flexion"}', '{"glute_bridge"}', true, false, 'Band round the neck and under the feet. Teaches the hinge with the resistance in the right place and nothing to drop.', 'resistance_dynamic', 'sets_reps_load', '{}', '{}', '[]'::jsonb, '{}', 2, false, 'none', false, false, false, '{}', 'band_good_morning', null, 'internally_reviewed', true, true, false, null, '[]'::jsonb, '{}', 'minimal', 'primary', 'lengthened', true, 'hamstring_eccentric'),
  ('band_overhead_press', 'Band Overhead Press', 'vertical_push', '{"strength"}', '{"front_delts"}', '{"triceps","core"}', '{"bands"}', 1, 2, true, false, false, false, 15, 'reps', 12, 20, false, null, 2, '{"shoulder_overhead"}', '{"pike_push_up"}', true, false, 'Standing on the band. The resistance rises through the range, which happens to match where the shoulder is strongest.', 'resistance_dynamic', 'sets_reps_load', '{}', '{}', '[]'::jsonb, '{}', 1, false, 'none', true, false, false, '{}', 'band_overhead_press', null, 'internally_reviewed', true, true, false, null, '[]'::jsonb, '{}', 'minimal', 'primary', 'lengthened', true, 'standard_compound'),
  ('wall_walk', 'Wall Walk', 'vertical_push', '{"calisthenics","conditioning"}', '{"front_delts"}', '{"triceps","core"}', '{"wall","floor_space"}', 3, 4, true, false, false, false, 10, 'reps', 3, 6, false, null, 4, '{"shoulder_overhead","wrist"}', '{"elevated_pike_push_up"}', true, false, '', 'resistance_dynamic', 'sets_reps_load', '{}', '{}', '[]'::jsonb, '{}', 3, false, 'none', true, false, false, '{"pike_push_up"}', 'wall_walk', null, 'internally_reviewed', true, true, false, null, '[]'::jsonb, '{}', 'minimal', 'primary', 'lengthened', true, 'standard_compound'),
  ('backpack_carry', 'Loaded Backpack Carry', 'carry', '{"strength"}', '{"core","forearms"}', '{"traps","glutes"}', '{"backpack"}', 1, 3, true, false, false, false, 30, 'seconds', 30, 60, true, 2.0, 2, '{}', '{"farmers_carry"}', true, false, 'Books and water bottles are a perfectly good load. The carry pattern is too useful to reserve for people who own handles.', 'resistance_isometric', 'sets_duration_load', '{}', '{}', '[]'::jsonb, '{}', 1, false, 'none', false, true, false, '{}', 'backpack_carry', null, 'internally_reviewed', true, true, false, 6, '[]'::jsonb, '{}', 'minimal', 'primary', 'held', false, 'standard_compound'),
  ('suitcase_hold', 'Suitcase Hold', 'carry', '{"strength"}', '{"obliques","forearms"}', '{"traps"}', '{}', 1, 3, true, false, false, true, 15, 'seconds', 20, 45, true, 2.0, 2, '{}', '{"suitcase_carry"}', true, false, 'Standing still under an uneven load. The version for anyone without twenty metres of floor.', 'resistance_isometric', 'sets_duration_load', '{"core_anti_lateral_flexion"}', '{}', '[["backpack","dumbbells","kettlebell"]]'::jsonb, '{}', 1, false, 'none', false, false, false, '{}', 'suitcase_hold', null, 'internally_reviewed', true, true, false, 6, '[]'::jsonb, '{}', 'minimal', 'primary', 'held', false, 'standard_compound'),
  ('tibialis_raise', 'Tibialis Raise', 'isolation_lower', '{"strength"}', '{"tibialis"}', '{}', '{"wall"}', 1, 1, true, false, false, false, 5, 'reps', 15, 25, false, null, 1, '{}', '{"heel_walk"}', true, false, 'The muscle on the front of the shin, which almost nobody trains and which is implicated in shin splints and in slowing down safely.', 'resistance_dynamic', 'sets_reps_load', '{}', '{}', '[]'::jsonb, '{}', 1, false, 'none', false, false, false, '{}', 'tibialis_raise', null, 'internally_reviewed', true, true, false, null, '[]'::jsonb, '{}', 'minimal', 'accessory', 'lengthened', true, 'grip_and_small'),
  ('heel_walk', 'Heel Walk', 'isolation_lower', '{"strength"}', '{"tibialis"}', '{}', '{"floor_space"}', 1, 2, true, false, false, false, 0, 'steps', 15, 30, false, null, 1, '{}', '{"tibialis_raise"}', true, false, '', 'resistance_dynamic', 'sets_reps_load', '{}', '{}', '[]'::jsonb, '{}', 1, false, 'none', false, false, false, '{}', 'heel_walk', null, 'internally_reviewed', true, true, false, null, '[]'::jsonb, '{}', 'minimal', 'accessory', 'lengthened', false, 'grip_and_small'),
  ('short_foot', 'Short Foot Drill', 'isolation_lower', '{"mobility","balance"}', '{"foot_intrinsics"}', '{"ankle_stabilisers"}', '{}', 2, 2, true, false, false, false, 0, 'seconds', 10, 30, false, null, 1, '{}', '{"single_leg_stand"}', true, false, 'Drawing the ball of the foot toward the heel without curling the toes. Feels like nothing and changes how a single-leg stand behaves.', 'skill_drill', 'sets_duration_quality', '{}', '{}', '[]'::jsonb, '{}', 2, false, 'none', false, false, false, '{}', 'short_foot', null, 'internally_reviewed', true, true, false, null, '[]'::jsonb, '{}', 'minimal', 'accessory', 'held', false, 'grip_and_small'),
  ('plate_pinch', 'Plate Pinch', 'isolation_upper', '{"strength"}', '{"forearms"}', '{}', '{"plates"}', 1, 1, true, false, false, false, 15, 'seconds', 20, 45, true, 1.25, 1, '{}', '{"towel_hang","dead_hang"}', true, false, 'Pinch grip, which is the one that fails first on a deadlift and never gets trained by straps.', 'resistance_isometric', 'sets_duration_load', '{}', '{}', '[]'::jsonb, '{}', 1, false, 'none', false, false, false, '{}', 'plate_pinch', null, 'internally_reviewed', true, true, false, 6, '[]'::jsonb, '{}', 'minimal', 'accessory', 'held', false, 'grip_and_small'),
  ('towel_hang', 'Towel Hang', 'isolation_upper', '{"strength"}', '{"forearms"}', '{"lats"}', '{"pull_up_bar","towel"}', 2, 2, true, false, false, false, 20, 'seconds', 15, 40, false, null, 2, '{}', '{"dead_hang"}', true, false, '', 'resistance_isometric', 'sets_duration_load', '{"vertical_pull"}', '{}', '[]'::jsonb, '{}', 2, false, 'none', false, false, false, '{}', 'towel_hang', null, 'internally_reviewed', true, true, false, null, '[]'::jsonb, '{}', 'minimal', 'accessory', 'held', false, 'grip_and_small'),
  ('wrist_roller', 'Wrist Roller', 'isolation_upper', '{"strength"}', '{"forearms"}', '{}', '{"rope","plates"}', 1, 1, true, false, false, false, 40, 'rounds', 2, 4, true, 1.25, 2, '{}', '{"plate_pinch"}', true, false, '', 'resistance_dynamic', 'sets_reps_load', '{}', '{}', '[]'::jsonb, '{}', 1, false, 'none', false, false, false, '{}', 'wrist_roller', null, 'internally_reviewed', true, true, false, 6, '[]'::jsonb, '{}', 'minimal', 'accessory', 'mid', false, 'grip_and_small'),
  ('neck_isometric', 'Neck Isometric', 'isolation_upper', '{"strength"}', '{"neck"}', '{}', '{}', 1, 1, true, false, false, false, 0, 'seconds', 10, 20, false, null, 1, '{}', '{"chin_tuck"}', true, false, 'Hand-resisted in four directions. Relevant to contact sports and to anyone whose neck complains under a loaded carry.', 'resistance_isometric', 'sets_duration_load', '{}', '{}', '[]'::jsonb, '{}', 1, false, 'none', false, false, false, '{}', 'neck_isometric', null, 'internally_reviewed', true, true, false, null, '[]'::jsonb, '{}', 'minimal', 'accessory', 'held', false, 'grip_and_small'),
  ('chin_tuck', 'Chin Tuck', 'isolation_upper', '{"mobility"}', '{"deep_neck_flexors"}', '{}', '{}', 1, 1, true, false, false, false, 0, 'seconds', 5, 10, false, null, 1, '{}', '{"neck_isometric"}', true, false, '', 'mobility_drill', 'sets_duration_or_reps', '{}', '{}', '[]'::jsonb, '{}', 1, false, 'none', false, false, false, '{}', 'chin_tuck', null, 'internally_reviewed', true, true, false, null, '[]'::jsonb, '{}', 'minimal', 'accessory', 'held', false, 'grip_and_small'),
  ('side_plank_knees', 'Side Plank from Knees', 'core_anti_lateral_flexion', '{"strength"}', '{"obliques"}', '{"glutes"}', '{"mat"}', 1, 2, true, false, false, true, 5, 'seconds', 20, 45, false, null, 1, '{}', '{"side_plank"}', true, false, '', 'resistance_isometric', 'sets_duration_load', '{}', '{}', '[]'::jsonb, '{}', 1, false, 'none', false, false, false, '{}', 'side_plank_knees', null, 'internally_reviewed', true, true, false, null, '[]'::jsonb, '{}', 'minimal', 'primary', 'held', false, 'core_braced'),
  ('dumbbell_side_bend', 'Dumbbell Side Bend', 'core_anti_lateral_flexion', '{"strength"}', '{"obliques"}', '{"spinal_erectors"}', '{"dumbbells"}', 1, 2, true, false, false, false, 15, 'reps', 10, 15, true, 2.0, 2, '{}', '{"suitcase_hold"}', true, false, 'Loaded on one side only. Trains the side that resists, not the side that bends.', 'resistance_dynamic', 'sets_reps_load', '{}', '{}', '[]'::jsonb, '{}', 1, false, 'none', false, false, false, '{}', 'dumbbell_side_bend', null, 'internally_reviewed', true, true, false, 6, '[]'::jsonb, '{}', 'minimal', 'accessory', 'lengthened', true, 'core_braced')
