insert into public.cardio_modalities (
  id, name, equipment, impact_level, skill, upper_share, lower_share,
  supports_zones, warmup_seconds, contraindications, outdoor, measures,
  leg_interference, notes
) values
  ('cycle_stationary', 'Stationary Bike', '{"stationary_bike"}', 'none', 1, 0.0, 1.0, '{"z1","z2","tempo","threshold","vo2","sprint"}', 120, '{}', false, '{"duration","distance","watts"}', 0.4, 'The default aerobic option inside a muscle-building block: it interferes with leg hypertrophy less than running does.'),
  ('cycle_outdoor', 'Outdoor Cycling', '{"bicycle"}', 'none', 2, 0.0, 1.0, '{"z1","z2","tempo","threshold"}', 300, '{}', true, '{"duration","distance","elevation"}', 0.4, 'Traffic makes true interval control unreliable, so the hard prescriptions are held back for indoor or closed roads.'),
  ('treadmill', 'Treadmill', '{"treadmill"}', 'moderate', 1, 0.0, 1.0, '{"z1","z2","tempo","threshold","vo2","sprint"}', 180, '{"knee_impact"}', false, '{"duration","distance","incline"}', 1.0, ''),
  ('run_outdoor', 'Outdoor Running', '{"outdoor_space"}', 'moderate', 2, 0.0, 1.0, '{"z1","z2","tempo","threshold","vo2","sprint"}', 300, '{"knee_impact"}', true, '{"duration","distance","elevation"}', 1.0, ''),
  ('walk', 'Walking', '{}', 'low', 1, 0.0, 1.0, '{"z1","z2"}', 0, '{}', false, '{"duration","distance","steps"}', 0.1, 'Needs no equipment and no shower, which is why it survives contact with a real week better than any other modality.'),
  ('incline_walk', 'Incline Treadmill Walk', '{"treadmill"}', 'low', 1, 0.0, 1.0, '{"z1","z2","tempo"}', 120, '{}', false, '{"duration","distance","incline"}', 0.3, ''),
  ('row_erg', 'Rowing Machine', '{"rower"}', 'none', 3, 0.35, 0.65, '{"z1","z2","tempo","threshold","vo2","sprint"}', 180, '{"low_back_flexion"}', false, '{"duration","distance","watts"}', 0.6, 'Technique-dependent: a poor sequence turns it into a low-back exercise, so it is not the first choice for an unsupervised beginner.'),
  ('ski_erg', 'Ski Erg', '{"ski_erg"}', 'none', 2, 0.6, 0.4, '{"z1","z2","tempo","threshold","vo2","sprint"}', 120, '{}', false, '{"duration","distance","watts"}', 0.3, ''),
  ('air_bike', 'Air Bike', '{"air_bike"}', 'none', 1, 0.35, 0.65, '{"z2","threshold","vo2","sprint"}', 120, '{}', false, '{"duration","calories","watts"}', 0.5, 'Resistance rises with effort, so it self-limits at the top end and suits intervals better than steady work.'),
  ('elliptical', 'Elliptical', '{"elliptical"}', 'none', 1, 0.25, 0.75, '{"z1","z2","tempo","threshold","vo2","sprint"}', 120, '{}', false, '{"duration","distance"}', 0.5, ''),
  ('stair_climber', 'Stair Climber', '{"stair_climber"}', 'low', 1, 0.0, 1.0, '{"z1","z2","tempo","threshold"}', 120, '{}', false, '{"duration","floors"}', 0.7, ''),
  ('swim', 'Swimming', '{"pool"}', 'none', 4, 0.65, 0.35, '{"z1","z2","tempo","threshold","vo2","sprint"}', 300, '{}', false, '{"duration","distance"}', 0.2, 'The only modality where poor technique costs more than poor fitness, so distance targets mean little until the stroke holds.'),
  ('jump_rope', 'Jump Rope', '{"jump_rope"}', 'high', 3, 0.2, 0.8, '{"z2","tempo","vo2","sprint"}', 60, '{"knee_impact","achilles"}', false, '{"duration","reps"}', 0.6, ''),
  ('sled_push_drag', 'Sled Push or Drag', '{"sled"}', 'none', 2, 0.2, 0.8, '{"tempo","threshold","vo2","sprint"}', 180, '{}', false, '{"duration","distance"}', 0.9, 'Almost no eccentric load, so it buys conditioning without the soreness that limits the next lower-body session.'),
  ('shadow_box', 'Shadow Boxing', '{}', 'low', 2, 0.7, 0.3, '{"z2","tempo","vo2"}', 120, '{}', false, '{"duration","rounds"}', 0.2, '')
on conflict (id) do update set
  name = excluded.name, equipment = excluded.equipment,
  impact_level = excluded.impact_level, skill = excluded.skill,
  upper_share = excluded.upper_share, lower_share = excluded.lower_share,
  supports_zones = excluded.supports_zones,
  warmup_seconds = excluded.warmup_seconds,
  contraindications = excluded.contraindications, outdoor = excluded.outdoor,
  measures = excluded.measures, leg_interference = excluded.leg_interference,
  notes = excluded.notes;

insert into public.cardio_prescriptions (
  id, name, zone, structure, duration_low, duration_high, unit, work_seconds,
  rest_seconds, rounds_low, rounds_high, rpe, skill, fatigue_cost, weekly_cap,
  prereq_base_weeks, adaptations, notes
) values
  ('recovery', 'Recovery', 'z1', 'steady', 15, 40, 'minutes', null, null, null, null, 2, 1, 1, null, 0, '{"recovery","blood_flow"}', 'Deliberately easy enough that it costs nothing: if it needs willpower it is the wrong intensity.'),
  ('base_z2', 'Zone 2 Base', 'z2', 'steady', 20, 60, 'minutes', null, null, null, null, 4, 1, 2, null, 0, '{"aerobic_base","fat_oxidation","capillarisation"}', 'Conversational the whole way. Most people ride this too hard, which is why the app cues by breath rather than by heart rate alone.'),
  ('long_steady', 'Long Steady', 'z2', 'steady', 60, 180, 'minutes', null, null, null, null, 4, 1, 3, 1, 4, '{"aerobic_base","durability","fuelling_practice"}', 'The endurance session that actually builds an event finish. Capped at one a week because recovery, not willingness, is the limit.'),
  ('tempo', 'Tempo', 'tempo', 'steady', 20, 40, 'minutes', null, null, null, null, 6, 1, 3, 2, 3, '{"lactate_clearance","aerobic_power"}', 'Comfortably hard, sustainable, not a race. Full sentences become short sentences.'),
  ('cruise_intervals', 'Cruise Intervals', 'threshold', 'intervals', 24, 40, 'minutes', 480, 90, 3, 5, 7, 2, 4, 1, 6, '{"lactate_threshold","aerobic_power"}', ''),
  ('threshold_intervals', 'Threshold Intervals', 'threshold', 'intervals', 20, 32, 'minutes', 240, 60, 4, 8, 8, 2, 4, 1, 6, '{"lactate_threshold","aerobic_power"}', ''),
  ('vo2_long', 'VO2 Intervals, Long', 'vo2', 'intervals', 20, 32, 'minutes', 180, 180, 4, 6, 9, 2, 5, 1, 8, '{"vo2max","cardiac_output"}', 'Equal work and rest. The last minute of each interval is where the adaptation lives, which is why the rest is not shortened to make it feel harder.'),
  ('vo2_short', 'VO2 Intervals, Short', 'vo2', 'intervals', 16, 26, 'minutes', 60, 60, 8, 14, 9, 2, 4, 1, 6, '{"vo2max","anaerobic_capacity"}', ''),
  ('sprint_intervals', 'Sprint Intervals', 'sprint', 'intervals', 12, 20, 'minutes', 20, 100, 6, 10, 10, 3, 5, 1, 8, '{"anaerobic_power","vo2max"}', 'Genuinely all out, which means the rest is long. Shortening it produces a mediocre threshold session wearing a sprint label.'),
  ('fartlek', 'Fartlek', 'tempo', 'variable', 20, 45, 'minutes', null, null, null, null, 6, 2, 3, 2, 4, '{"aerobic_power","pace_awareness"}', 'Unstructured surges by feel. Useful when a session must survive traffic lights, hills and a dog.'),
  ('walk_run', 'Walk-Run', 'z2', 'intervals', 15, 40, 'minutes', 60, 90, 6, 14, 4, 1, 2, null, 0, '{"aerobic_base","impact_tolerance"}', 'The honest entry point for a runner from scratch. Progression is in total minutes and in the shrinking walk, never in pace.'),
  ('brick', 'Brick', 'z2', 'transition', 30, 90, 'minutes', null, null, null, null, 5, 2, 4, 1, 8, '{"transition_tolerance","durability"}', 'Two modalities back to back with no gap. Trains the legs for the first kilometre off the bike, which is the part that surprises people.'),
  ('race_pace', 'Race Pace', 'threshold', 'steady', 15, 60, 'minutes', null, null, null, null, 7, 2, 4, 1, 10, '{"pace_discipline","race_specificity"}', 'Rehearses the exact intensity of the event, including the fuelling, so nothing on the day is new.')
on conflict (id) do update set
  name = excluded.name, zone = excluded.zone, structure = excluded.structure,
  duration_low = excluded.duration_low, duration_high = excluded.duration_high,
  unit = excluded.unit, work_seconds = excluded.work_seconds,
  rest_seconds = excluded.rest_seconds, rounds_low = excluded.rounds_low,
  rounds_high = excluded.rounds_high, rpe = excluded.rpe, skill = excluded.skill,
  fatigue_cost = excluded.fatigue_cost, weekly_cap = excluded.weekly_cap,
  prereq_base_weeks = excluded.prereq_base_weeks,
  adaptations = excluded.adaptations, notes = excluded.notes;

